/**
 * Daily work journals (v0.7; the UI calls this 工作日志, the file names and API
 * keep the historical `reports` naming).
 *
 * A journal is generated by a normal Session: the Host gathers the day's REAL
 * content — every queue task outcome plus the actual user question and final
 * answer of each active DSH workspace session — composes a fixed-format
 * request, a model writes a concrete journal, and the last assistant text is
 * written atomically to `<dir>/<YYYY-MM-DD>.md`. A 30s timer generates today's
 * journal once the configured local time passes.
 *
 * The fixed four sections are part of the v0.7 contract
 * (`docs/v0.7-contract.md` §2): 今日要点 / 逐项记录 / 待跟进 / 明天建议. The
 * journal must carry concrete outcomes, never status counts or filler, and a
 * day without activity still produces a short readable journal.
 */
import {
  existsSync,
  mkdirSync,
  readdirSync,
  readFileSync,
  renameSync,
  statSync,
  writeFileSync,
} from 'node:fs'
import { join } from 'node:path'
import {
  DEFAULT_REPORT_TIME,
  HttpError,
  REPORT_DATE_PATTERN,
  REPORT_TIME_PATTERN,
} from './store.js'

const REPORT_TICK_MS = 30_000
const REPORT_POLL_MS = 1_000
const REPORT_MAX_WAIT_MS = 10 * 60 * 1000
const REPORT_LIST_LIMIT = 200
const FILE_PATTERN = /^\d{4}-\d{2}-\d{2}\.md$/

export const SESSION_ASK_LIMIT = 400
export const SESSION_ANSWER_LIMIT = 1500
export const MAX_SESSION_DIGESTS = 8
const JOURNAL_MAX_CHARS = 3000
const JOURNAL_BULLET_LIMIT = 300
const JOURNAL_SECTION_LIMITS = [6, 12, 8, 4]

/** Fixed four sections; text and order are part of the v0.7 contract. */
export const REPORT_SECTIONS = [
  '## 一、今日要点',
  '## 二、逐项记录',
  '## 三、待跟进',
  '## 四、明天建议',
]

const STATUS_LABELS = {
  idea: '想法',
  pending: '队列中',
  running: '执行中',
  paused: '已暂停',
  blocked: '等你回复',
  done: '已完成',
  failed: '失败',
  cancelled: '已取消',
}

function pad(value) {
  return String(value).padStart(2, '0')
}

/** Local calendar date, `YYYY-MM-DD`. */
export function localDateString(time = Date.now()) {
  const date = new Date(time)
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`
}

/** Local wall-clock time, `HH:mm`. */
export function localTimeString(time = Date.now()) {
  const date = new Date(time)
  return `${pad(date.getHours())}:${pad(date.getMinutes())}`
}

/** [start, end) epoch bounds of one local calendar day; undefined if invalid. */
export function dayRange(date) {
  const text = String(date || '')
  if (!REPORT_DATE_PATTERN.test(text)) return undefined
  const [year, month, day] = text.split('-').map(Number)
  const start = new Date(year, month - 1, day).getTime()
  const check = new Date(start)
  if (check.getFullYear() !== year || check.getMonth() !== month - 1 || check.getDate() !== day) {
    return undefined
  }
  const end = new Date(year, month - 1, day + 1).getTime()
  return { start, end }
}

/**
 * The timer's due rule: enabled, the local clock has passed the configured
 * time, today has no successful journal yet, and no generation is in flight.
 */
export function isReportDue(settings, now = Date.now()) {
  if (!settings || settings.enabled !== true) return false
  const time = REPORT_TIME_PATTERN.test(String(settings.time || ''))
    ? settings.time
    : DEFAULT_REPORT_TIME
  if (localTimeString(now) < time) return false
  if (settings.lastDate === localDateString(now)) return false
  if (settings.generatingDate) return false
  return true
}

const REPORT_HEADING = /^# \d{4}-\d{2}-\d{2}/
const JOURNAL_TITLE = '工作日志'

/**
 * Extract exactly the journal body from a model answer.
 *
 * The model sometimes narrates around its answer ("已生成并保存…") or echoes a
 * heading twice; only the first `# YYYY-MM-DD …` line onwards is the journal.
 * When no heading exists the standard title is prepended. The result always
 * has trimmed trailing whitespace and exactly one trailing newline.
 */
export function extractReportBody(text, date) {
  const normalized = String(text || '').replace(/\r\n?/g, '\n')
  const lines = normalized.split('\n')
  let start = -1
  for (let index = 0; index < lines.length; index += 1) {
    if (REPORT_HEADING.test(lines[index].trim())) {
      start = index
      break
    }
  }
  let body
  if (start >= 0) {
    const heading = lines[start].trim()
    body = [heading, ...lines.slice(start + 1)].join('\n')
  } else {
    body = `# ${date} ${JOURNAL_TITLE}\n\n${normalized}`
  }
  body = body.trimEnd()
  if (!body) body = `# ${date} ${JOURNAL_TITLE}`
  return `${body}\n`
}

/** Backwards-compatible name: hosting writes the repaired body. */
export function ensureTitle(text, date) {
  return extractReportBody(text, date)
}

// ---------------------------------------------------------------------------
// Real session content (v0.7): user question + final answer per DSH session.
// ---------------------------------------------------------------------------

const LESSON_PROMPT_HEADING = '## 任务管家 · 过往复盘经验'

/**
 * Older versions prefixed a task prompt with an injected lesson block; the
 * journal must show what the USER actually asked, so drop that block.
 */
function stripInjectedLessons(text) {
  const value = String(text || '')
  const index = value.indexOf(LESSON_PROMPT_HEADING)
  if (index < 0) return value.trim()
  const rest = value.slice(index)
  const lines = rest.split('\n')
  for (let i = 1; i < lines.length; i += 1) {
    if (lines[i].trim() === '---') return lines.slice(i + 1).join('\n').trim()
  }
  return value.slice(0, index).trim()
}

function clipText(text, limit) {
  const clean = String(text || '').trim()
  return clean.length > limit ? clean.slice(0, limit) : clean
}

/**
 * Pull the useful content out of a session transcript: the first human message
 * (what the user asked, ≤ askLimit chars) and the last assistant message (the
 * final answer/conclusion, ≤ answerLimit chars).
 *
 * Accepts either the `bridge.transcript` result (`{ messages: [...] }`) or a
 * bare messages array. A missing / unreadable transcript yields empty strings.
 */
export function extractSessionDigest(input, options = {}) {
  const askLimit = Number.isFinite(options.askLimit) ? Math.max(1, Math.floor(options.askLimit)) : SESSION_ASK_LIMIT
  const answerLimit = Number.isFinite(options.answerLimit)
    ? Math.max(1, Math.floor(options.answerLimit))
    : SESSION_ANSWER_LIMIT
  const messages = Array.isArray(input)
    ? input
    : (input && Array.isArray(input.messages) ? input.messages : [])
  let ask = ''
  let answer = ''
  for (const message of messages) {
    if (!message || typeof message !== 'object') continue
    const text = typeof message.text === 'string' ? message.text.trim() : ''
    if (!text) continue
    if (message.role === 'user') {
      if (!ask) ask = stripInjectedLessons(text)
    } else if (message.role === 'assistant') {
      answer = text
    }
  }
  return { ask: clipText(ask, askLimit), answer: clipText(answer, answerLimit) }
}

/**
 * Pick the DSH workspace sessions with activity on `date` and read their real
 * content. Newest activity first, at most `limit` sessions; a session whose
 * transcript cannot be read is silently skipped.
 */
export async function collectSessionDigests({ store, bridge, date, limit = MAX_SESSION_DIGESTS } = {}) {
  const range = dayRange(date)
  const tasks = store && Array.isArray(store.tasks) ? store.tasks : []
  const candidates = []
  for (const task of tasks) {
    if (!task || task.source !== 'session' || !task.sessionId) continue
    const stamps = [task.createdAt, task.startedAt, task.endedAt, task.updatedAt].filter(Number.isFinite)
    if (stamps.length === 0) continue
    if (range && !stamps.some(time => time >= range.start && time < range.end)) continue
    candidates.push({ task, activity: Math.max(...stamps) })
  }
  candidates.sort((left, right) => right.activity - left.activity)
  const max = Number.isFinite(limit) ? Math.max(1, Math.floor(limit)) : MAX_SESSION_DIGESTS
  const digests = []
  if (!bridge || typeof bridge.transcript !== 'function') return digests
  for (const item of candidates.slice(0, max)) {
    const task = item.task
    let transcript = null
    try {
      transcript = await bridge.transcript(task.sessionId)
    } catch {
      transcript = null
    }
    if (!transcript) continue
    const digest = extractSessionDigest(transcript)
    if (!digest.ask && !digest.answer) continue
    digests.push({
      id: task.id,
      title: typeof task.title === 'string' ? task.title : '',
      cwd: typeof task.cwd === 'string' ? task.cwd : '',
      ask: digest.ask,
      answer: digest.answer,
    })
  }
  return digests
}

// ---------------------------------------------------------------------------
// Data helpers.
// ---------------------------------------------------------------------------

function errorMessage(error) {
  if (!error) return '未知错误'
  if (typeof error === 'string') return error
  if (typeof error.message === 'string' && error.message) return error.message
  try {
    return JSON.stringify(error)
  } catch {
    return String(error)
  }
}

function sleep(ms) {
  return new Promise(resolve => {
    const handle = setTimeout(resolve, ms)
    if (handle && typeof handle.unref === 'function') handle.unref()
  })
}

function cleanInline(text) {
  return String(text || '')
    .replace(/\r?\n+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
}

/** First sentence-ish chunk: keeps concrete content, drops trailing rambling. */
function firstSentence(text, limit = 300) {
  const clean = cleanInline(text)
  if (clean === '') return ''
  const match = /^(.{1,400}?[。！？!?；;])/.exec(clean)
  const value = match ? match[1] : clean
  return value.length > limit ? `${value.slice(0, limit)}…` : value
}

/** The concrete outcome of one task: final answer, failure reason or last word. */
function taskOutcome(task, limit = SESSION_ANSWER_LIMIT) {
  if (!task || typeof task !== 'object') return ''
  if (task.result && typeof task.result.finalAnswer === 'string' && task.result.finalAnswer.trim()) {
    return clipText(task.result.finalAnswer, limit)
  }
  if (typeof task.error === 'string' && task.error.trim()) return clipText(task.error, Math.min(limit, 600))
  if (typeof task.lastMessage === 'string' && task.lastMessage.trim()) {
    return clipText(task.lastMessage, Math.min(limit, 600))
  }
  return ''
}

/** What the user asked for: the task prompt (or the imported session title). */
function taskAskText(task, limit = 400) {
  if (!task || typeof task !== 'object') return ''
  if (typeof task.prompt === 'string' && task.prompt.trim()) {
    return clipText(stripInjectedLessons(task.prompt), limit)
  }
  return clipText(task.title, limit)
}

function statusLabel(status) {
  return STATUS_LABELS[status] || status
}

function compactBullet(text, limit = JOURNAL_BULLET_LIMIT) {
  const clean = String(text || '').replace(/\s+/g, ' ').trim()
  return clean.length > limit ? `${clean.slice(0, limit)}…` : clean
}

// ---------------------------------------------------------------------------
// Prompt + deterministic fallback.
// ---------------------------------------------------------------------------

function promptTaskLine(task) {
  const parts = [`[${statusLabel(task.status)}] ${task.title || '未命名任务'}`]
  const ask = firstSentence(taskAskText(task), 300)
  if (ask) parts.push(`你交代了：${ask}`)
  const outcome = taskOutcome(task, 1200)
  if (outcome) parts.push(`产出/结果：${cleanInline(outcome)}`)
  return `- ${parts.join('；')}`
}

function promptDigestLines(sessionDigests) {
  if (sessionDigests.length === 0) return ['- 无']
  return sessionDigests.map(digest => {
    const title = cleanInline(digest.title || 'DSH 会话')
    const ask = cleanInline(digest.ask) || '（无首条提问记录）'
    const answer = cleanInline(digest.answer) || '（无最后结论记录）'
    return `- 会话「${title}」\n  用户问：${ask}\n  最后结论：${answer}`
  })
}

/**
 * The fixed v0.7 journal request. The model is asked for concrete outcomes and
 * conclusions, not a status report; the Host repairs/normalises the answer and
 * falls back to a deterministic journal when the structure is unusable.
 */
export function buildAiSummaryPrompt({
  date,
  queueTasks = [],
  sessionTasks = [],
  sessionDigests = [],
  ideas = [],
  unfinished = [],
}) {
  const digests = Array.isArray(sessionDigests) ? sessionDigests : []
  const completed = queueTasks.filter(task => task.status === 'done')
  const failed = queueTasks.filter(task => task.status === 'failed')
  const queueUnfinished = (Array.isArray(unfinished) ? unfinished : [])
    .filter(task => task && task.source !== 'session')
  const active = queueUnfinished.filter(task =>
    task.status === 'running' || task.status === 'paused' || task.status === 'blocked')
  const queued = queueUnfinished.filter(task => task.status === 'pending')
  const earlier = completed.length + failed.length
  const lines = [
    `你是用户的私人助理，请根据下面提供的 ${date} 真实工作数据，写一份**工作日志**（简体中文 Markdown），不是状态报告。`,
    '',
    '硬性要求：',
    `1. 只输出 Markdown 正文；第一行必须恰好是「# ${date} 工作日志」；不要寒暄、不要解释、不要输出代码块围栏。`,
    '2. 必须严格使用以下四个二级标题，文字与顺序都不能改：',
    REPORT_SECTIONS[0],
    REPORT_SECTIONS[1],
    REPORT_SECTIONS[2],
    REPORT_SECTIONS[3],
    '3. 「今日要点」写 3–5 条，每条必须是具体结论/产出（做了什么、发现了什么、交付了什么）；允许写具体数字、文件名、文档、链接、结论；**禁止**「完成 X 项」「整体平稳」「顺利推进」这类空话。',
    '4. 「逐项记录」每个任务/会话一条，格式「- **标题**：你交代了……；我做了……；结论/产出是……」每条 1–3 句；会话任务必须写清用户实际问的是什么、最后结论是什么，不能只写标题。',
    '5. 「待跟进」只写真实未完成、待验证或等对方的事；没有就写「- 无」。',
    '6. 「明天建议」写 1–3 条具体动作，能直接执行或决策。',
    '7. 总长 600–900 字；不写 token、模型名、耗时、优先级、会话 ID 等技术细节；不要编造数据之外的内容。',
    '8. 输入里「DSH 会话摘要」包含用户的真实提问与最后结论，优先使用其中的具体内容。',
    '',
    `今天是 ${date}。数据如下：`,
    '',
    '队列任务（含结果或错误）：',
    ...(queueTasks.length ? queueTasks.slice(0, 16).map(promptTaskLine) : ['- 无']),
    '',
    'DSH 会话摘要（真实会话内容，优先使用）：',
    ...promptDigestLines(digests),
    '',
    '今天记下的想法：',
    ...(ideas.length
      ? ideas.slice(0, 5).map(idea => `- ${idea.title || '想法'}：${cleanInline(firstSentence(taskAskText(idea), 300))}`)
      : ['- 无']),
    '',
    '当前未完成的任务（含跨天）：',
    ...(queueUnfinished.length
      ? queueUnfinished.slice(0, 12).map(task => `- [${statusLabel(task.status)}] ${task.title || '未命名任务'}：${cleanInline(firstSentence(taskOutcome(task), 200)) || '暂无最新进展'}`)
      : ['- 无']),
  ].join('\n')
  // Keep the numeric counts out of the prompt body on purpose; they are only
  // used to phrase the empty-data hint below.
  if (earlier === 0 && active.length === 0 && queued.length === 0 && digests.length === 0) {
    lines.push('', '注意：今天没有记录到任务或会话活动，请写一份简短日志（今日要点说明无活动，明天建议从队列/想法里挑一件）。')
  }
  return lines
}

/**
 * Deterministic fallback journal, used when the model is unavailable or its
 * answer does not follow the fixed structure. It always carries concrete
 * content from the real session/question/result data — never status counts.
 */
export function buildDailySummary(data = {}) {
  const date = data.date || localDateString()
  const queueTasks = Array.isArray(data.queueTasks) ? data.queueTasks : []
  const sessionDigests = Array.isArray(data.sessionDigests) ? data.sessionDigests : []
  const ideas = Array.isArray(data.ideas) ? data.ideas : []
  const backlogIdeas = Array.isArray(data.backlogIdeas) ? data.backlogIdeas : ideas
  const unfinished = Array.isArray(data.unfinished)
    ? data.unfinished.filter(task => task && task.source !== 'session')
    : []
  const completed = queueTasks.filter(task => task.status === 'done')
  const failed = queueTasks.filter(task => task.status === 'failed')
  const active = unfinished.filter(task =>
    task.status === 'running' || task.status === 'paused' || task.status === 'blocked')
  const queued = unfinished.filter(task => task.status === 'pending')

  const lines = [`# ${date} ${JOURNAL_TITLE}`, '', REPORT_SECTIONS[0], '']
  const highlights = []
  for (const task of completed.slice(0, 4)) {
    const outcome = firstSentence(taskOutcome(task), 120)
    highlights.push(`- ${task.title || '任务'}${outcome ? `：${outcome}` : '：已完成'}`)
  }
  for (const task of failed.slice(0, 2)) {
    const reason = firstSentence(task.error || taskOutcome(task), 120)
    highlights.push(`- 「${task.title || '任务'}」失败${reason ? `：${reason}` : ''}`)
  }
  for (const digest of sessionDigests.slice(0, 3)) {
    const answer = firstSentence(digest.answer, 120)
    if (!answer) continue
    highlights.push(`- ${digest.title || 'DSH 会话'}：${answer}`)
  }
  if (highlights.length === 0) lines.push('今天没有记录到工作活动。')
  else lines.push(...highlights.slice(0, 6))

  lines.push('', REPORT_SECTIONS[1], '')
  const records = []
  for (const task of queueTasks.slice(0, 12)) {
    const ask = firstSentence(taskAskText(task), 200) || '（未记录描述）'
    const outcome = firstSentence(taskOutcome(task), 200)
    records.push(`- **${task.title || '任务'}**：你交代了「${ask}」；${outcome ? `结论/产出是「${outcome}」` : '目前仍在推进中'}`)
  }
  for (const digest of sessionDigests.slice(0, 8)) {
    const ask = firstSentence(digest.ask, 200) || '（无首条提问记录）'
    const answer = firstSentence(digest.answer, 300) || '（无最后结论记录）'
    records.push(`- **${digest.title || 'DSH 会话'}**：你问「${ask}」；结论是「${answer}」`)
  }
  for (const idea of ideas.slice(0, 3)) {
    records.push(`- **${idea.title || '想法'}**：今天记下的想法；内容：${firstSentence(taskAskText(idea), 200)}`)
  }
  if (records.length === 0) lines.push('- 无')
  else lines.push(...records.slice(0, 12))

  lines.push('', REPORT_SECTIONS[2], '')
  const followups = []
  for (const task of [...active, ...queued].slice(0, 8)) {
    const hint = firstSentence(taskOutcome(task), 160)
    followups.push(`- ${statusLabel(task.status)}「${task.title || '任务'}」${hint ? `：${hint}` : ''}`)
  }
  if (followups.length === 0) lines.push('- 无')
  else lines.push(...followups)

  lines.push('', REPORT_SECTIONS[3], '')
  const plan = []
  if (highlights.length === 0 && records.length === 0) {
    plan.push('- 从「想法」或队列里挑一件最想推进的事，先记下来再安排。')
  } else {
    for (const task of active.slice(0, 2)) plan.push(`- 继续「${task.title || '任务'}」，确认今天能否收尾。`)
    for (const task of failed.slice(0, 1)) plan.push(`- 复盘「${task.title || '任务'}」失败原因，再决定是否重试。`)
    for (const task of queued.slice(0, 2)) plan.push(`- 从「${task.title || '任务'}」开始执行（已在队列）。`)
    for (const idea of backlogIdeas.slice(0, 1)) plan.push(`- 评估想法「${idea.title || '想法'}」，决定是否加入队列。`)
  }
  if (plan.length === 0) plan.push('- 暂无新的安排，可以从队列或想法里挑一件。')
  lines.push(...plan.slice(0, 4))

  return `${lines.join('\n').replace(/\n{3,}/g, '\n\n').trim()}\n`
}

/** Technical metadata lines that must never leak into the journal body. */
function technicalLine(line) {
  return /(token|tokens|模型|路径|会话\s*(id|ID)|cwd|provider)/i.test(line)
}

/**
 * Model output is normalised before writing: a missing/reshuffled section
 * structure falls back to the deterministic journal; otherwise headings keep
 * their order, technical metadata lines are dropped, bullets are shortened and
 * each section is capped. Concrete numbers/files/links are preserved.
 */
export function normalizeAiSummary(text, date, data = {}) {
  const body = extractReportBody(text, date)
  const positions = REPORT_SECTIONS.map(section => body.indexOf(section))
  const structured = positions.every(index => index >= 0) &&
    positions.every((value, index) => index === 0 || value > positions[index - 1])
  if (!structured) {
    return { content: buildDailySummary({ date, ...(data || {}) }), fallback: true }
  }
  const sections = []
  let current = null
  for (const raw of body.split('\n')) {
    const line = raw.replace(/\s+$/, '')
    const heading = REPORT_SECTIONS.find(section => line.trim() === section)
    if (heading) {
      current = { heading, lines: [] }
      sections.push(current)
      continue
    }
    if (!current) continue
    if (line.trim() === '') {
      if (current.lines.length > 0 && current.lines[current.lines.length - 1] !== '') current.lines.push('')
      continue
    }
    const value = line.trim()
    if (technicalLine(value)) continue
    if (/^[-*+]\s+/.test(value)) {
      const bulletBody = compactBullet(value.replace(/^[-*+]\s+/, ''))
      if (bulletBody === '') continue
      current.lines.push(`- ${bulletBody}`)
    } else if (sections.length === 1) {
      // Only 今日要点 may carry a short prose paragraph; later sections are lists.
      current.lines.push(compactBullet(value, 300))
    }
  }
  const out = [`# ${date} ${JOURNAL_TITLE}`, '']
  sections.forEach((section, index) => {
    const limit = JOURNAL_SECTION_LIMITS[index] || 8
    let bullets = 0
    const kept = []
    for (const line of section.lines) {
      if (line.startsWith('- ')) {
        bullets += 1
        if (bullets > limit) continue
      }
      kept.push(line)
    }
    while (kept.length && kept[kept.length - 1] === '') kept.pop()
    if (kept.length === 0) kept.push('- 无')
    out.push(section.heading, '', ...kept, '')
  })
  let content = out.join('\n').replace(/\n{3,}/g, '\n\n').trim()
  if (content.length > JOURNAL_MAX_CHARS) content = `${content.slice(0, JOURNAL_MAX_CHARS).trimEnd()}…`
  return { content: `${content}\n`, fallback: false }
}

// ---------------------------------------------------------------------------
// Engine.
// ---------------------------------------------------------------------------

export function createReports({ ctx, store, bridge, notify, options = {} }) {
  const tickMs = Number.isFinite(options.tickMs) ? options.tickMs : REPORT_TICK_MS
  const pollMs = Number.isFinite(options.pollMs) ? options.pollMs : REPORT_POLL_MS
  const maxWaitMs = Number.isFinite(options.maxWaitMs) ? options.maxWaitMs : REPORT_MAX_WAIT_MS
  const push = typeof notify === 'function' ? notify : () => {}
  let timer = null
  let kickHandle = null
  let disposed = false

  function log(...args) {
    try {
      console.log('[personal-secretary]', ...args)
    } catch {
      // logging must never break journal generation
    }
  }

  function settings() {
    return store.settings.dailyReport
  }

  function reportDir() {
    return settings().dir
  }

  function today() {
    return localDateString(Date.now())
  }

  function list() {
    const dir = reportDir()
    let names = []
    try {
      names = readdirSync(dir)
    } catch {
      return []
    }
    const reports = []
    for (const name of names) {
      if (!FILE_PATTERN.test(name)) continue
      const path = join(dir, name)
      try {
        const stat = statSync(path)
        if (!stat.isFile()) continue
        reports.push({
          date: name.slice(0, -3),
          path,
          bytes: stat.size,
          updatedAt: stat.mtimeMs,
        })
      } catch {
        // A file removed between readdir and stat is simply skipped.
      }
    }
    reports.sort((left, right) => (left.date < right.date ? 1 : left.date > right.date ? -1 : 0))
    return reports.slice(0, REPORT_LIST_LIMIT)
  }

  function read(date) {
    const text = String(date || '')
    if (!REPORT_DATE_PATTERN.test(text) || !dayRange(text)) {
      throw new HttpError(400, '日期格式应为 YYYY-MM-DD')
    }
    const path = join(reportDir(), `${text}.md`)
    if (!existsSync(path)) return undefined
    return readFileSync(path, 'utf8')
  }

  function meta() {
    return { reports: list(), settings: { ...settings() } }
  }

  function writeReportFile(date, content) {
    const dir = reportDir()
    mkdirSync(dir, { recursive: true })
    const target = join(dir, `${date}.md`)
    const tmp = join(dir, `.${date}.md.${process.pid}.${Date.now()}.tmp`)
    writeFileSync(tmp, content, 'utf8')
    renameSync(tmp, target)
    return target
  }

  function collectData(date) {
    const range = dayRange(date)
    if (!range) throw new HttpError(400, '日期无效')
    const inDay = time => Number.isFinite(time) && time >= range.start && time < range.end
    const queueTasks = []
    const sessionTasks = []
    for (const task of store.tasks) {
      if (task.source === 'session') {
        if (inDay(task.updatedAt || task.createdAt)) sessionTasks.push(task)
        continue
      }
      // The idea backlog is listed separately, never as today's queue work.
      if (task.status === 'idea') continue
      const stamp = Number.isFinite(task.endedAt) ? task.endedAt : (task.updatedAt || task.createdAt)
      if (inDay(stamp)) queueTasks.push(task)
    }
    const unfinished = store.tasks.filter(task =>
      task.status === 'pending' || task.status === 'running' ||
      task.status === 'paused' || task.status === 'blocked')
    // The idea column is a backlog, not a day-specific bucket: every pending
    // idea is listed so the plan section can draw on it, while only ideas
    // captured on the journal's day count as "activity" for that day.
    const ideas = store.tasks.filter(task => task.status === 'idea')
    const todayIdeas = ideas.filter(task => inDay(task.createdAt))
    return { queueTasks, sessionTasks, ideas, todayIdeas, unfinished }
  }

  async function collect(date) {
    const dir = reportDir()
    mkdirSync(dir, { recursive: true })
    const data = collectData(date)
    // v0.7: read the real content of today's DSH sessions (question + answer).
    const sessionDigests = await collectSessionDigests({ store, bridge, date, limit: MAX_SESSION_DIGESTS })
    // v0.7: "activity" means day-specific work. The full idea backlog still
    // feeds the fallback's suggestions, but only ideas captured that day count
    // as journal activity.
    const todayIdeas = Array.isArray(data.todayIdeas) ? data.todayIdeas : data.ideas
    const reportData = { ...data, sessionDigests, ideas: todayIdeas, backlogIdeas: data.ideas }
    const hasActivity = data.queueTasks.length > 0 || sessionDigests.length > 0 || todayIdeas.length > 0
    if (!hasActivity) {
      // A day without activity still yields a short readable journal: no model
      // session needed, so the empty case is instant and free.
      log('no activity for', date, 'using the local short journal')
      return buildDailySummary({ date, ...reportData })
    }
    const prompt = buildAiSummaryPrompt({ date, ...reportData })
    const sessionId = await bridge.createSession({ cwd: dir })
    // The journal's Session is ours: it must not show up as a workspace import.
    store.ownSession(sessionId)
    await bridge.selectModel(sessionId, {
      provider: store.settings.provider,
      model: store.settings.model,
      reasoningEffort: store.settings.reasoningEffort,
    })
    const startedAt = Date.now()
    await bridge.prompt(sessionId, prompt)
    const deadline = startedAt + maxWaitMs
    for (;;) {
      if (disposed) throw new Error('工作日志生成已取消：插件已停止')
      const last = await bridge.lastTurnEnd(sessionId)
      if (last && last.reason) {
        const time = Number.isFinite(last.time) ? last.time : startedAt
        if (time >= startedAt - 1000) break
      }
      if (Date.now() >= deadline) throw new Error('工作日志生成超时（10 分钟）')
      await sleep(pollMs)
    }
    const summary = await bridge.summarize(sessionId)
    const text = String(summary.finalAnswer || '').trim()
    if (!text) {
      log('journal model returned no content, using the local journal')
      return buildDailySummary({ date, ...reportData })
    }
    const normalized = normalizeAiSummary(text, date, reportData)
    if (normalized.fallback) log('journal model output missed the fixed structure, using the local journal')
    return normalized.content
  }

  async function runGeneration(date) {
    try {
      const content = await collect(date)
      const reportPath = writeReportFile(date, content)
      store.updateDailyReport({
        lastDate: date,
        lastStatus: 'ok',
        lastError: null,
        lastGeneratedAt: Date.now(),
        generatingDate: null,
      })
      push('dailyReport', { date, content, path: reportPath })
    } catch (error) {
      log('journal generation failed:', errorMessage(error))
      store.updateDailyReport({
        lastStatus: 'failed',
        lastError: errorMessage(error),
        generatingDate: null,
      })
    }
  }

  /**
   * Reserve the generation slot and start it in the background. The HTTP layer
   * and the timer both call this; a second call while one is in flight is a
   * conflict.
   */
  function generate(date) {
    const target = date === undefined || date === null || date === ''
      ? today()
      : String(date).trim()
    if (!REPORT_DATE_PATTERN.test(target) || !dayRange(target)) {
      throw new HttpError(400, '日期格式应为 YYYY-MM-DD')
    }
    if (settings().generatingDate) throw new HttpError(409, '工作日志正在生成中')
    store.updateDailyReport({ generatingDate: target, lastStatus: 'running', lastError: null })
    void runGeneration(target)
    return { ok: true, date: target }
  }

  async function checkDue(now = Date.now()) {
    try {
      if (disposed) return
      if (!isReportDue(settings(), now)) return
      generate(localDateString(now))
    } catch (error) {
      log('journal due check failed:', errorMessage(error))
    }
  }

  function recoverStale() {
    const current = settings()
    if (current.lastStatus === 'running' || current.generatingDate) {
      store.updateDailyReport({
        lastStatus: 'failed',
        lastError: '上次工作日志生成未完成（进程已重启）',
        generatingDate: null,
      })
    }
  }

  function start() {
    if (timer || disposed) return
    recoverStale()
    timer = setInterval(() => { void checkDue() }, tickMs)
    if (typeof timer === 'object' && timer && typeof timer.unref === 'function') timer.unref()
    void checkDue()
  }

  function stop() {
    disposed = true
    if (timer) clearInterval(timer)
    timer = null
    if (kickHandle) clearTimeout(kickHandle)
    kickHandle = null
  }

  /** Immediate re-check after the settings row changed. */
  function kick() {
    if (disposed) return
    if (kickHandle) return
    kickHandle = setTimeout(() => {
      kickHandle = null
      void checkDue()
    }, 50)
    if (kickHandle && typeof kickHandle.unref === 'function') kickHandle.unref()
  }

  recoverStale()

  return {
    start,
    stop,
    kick,
    list,
    read,
    meta,
    today,
    generate,
    checkDue,
    recoverStale,
    reportDir,
    isGenerating: () => Boolean(settings().generatingDate),
  }
}

export {
  REPORT_TICK_MS,
  REPORT_POLL_MS,
  REPORT_MAX_WAIT_MS,
  REPORT_LIST_LIMIT,
  STATUS_LABELS,
}
